"Bir maddeye tıklayınca harita o güne gider, değişen yeri gösterir ve ayrıntı penceresi açılır (açıklama, görsel, kaynak). Böylece kronoloji ile harita birbirini doğrular.":["Հոդվածի վրա սեղմելիս քարտեզը գնում է այդ օրը, ցույց է տալիս փոխված վայրը և բացվում է մանրամասների պատուհանը (նկարագրություն, պատկեր, աղբյուր)։ Այսպես ժամանակագրությունն ու քարտեզը ստուգում են միմյանց։", "0c30189d"],
