"Bu atlas, zaman ilerledikçe devlet sınırlarının nasıl değiştiğini gösterir. Haritanın yanında o günün kronolojisi ve hükümdarı akar: bir madde okuduğunuzda haritada tam o değişimi görürsünüz.":["Այս ատլասը ցույց է տալիս, թե ինչպես են ժամանակի ընթացքում փոխվել պետությունների սահմանները։ Քարտեզի կողքին հոսում են տվյալ օրվա ժամանակագրությունն ու տիրակալը՝ երբ կարդում եք որևէ հոդված, քարտեզում տեսնում եք հենց այդ փոփոխությունը։", "f078a759"],
