"Kelimeleri boşlukla ayırarak yazın; hepsi geçen maddeler kalır. Tırnak içindeki ifade tek parça aranır. Büyük/küçük harf ve şapka farkı gözetilmez.":["Գրեք բառերը բացատներով բաժանած; մնում են այն հոդվածները, որոնցում կան բոլորը։ Չակերտների մեջ եղած արտահայտությունը որոնվում է որպես մեկ ամբողջություն։ Մեծատառի/փոքրատառի և գլխարկանիշի տարբերությունը հաշվի չի առնվում։", "f889bcce"],
"Kelimeleri boşlukla ayırın — HEPSİ geçen maddeler kalır (Mohaç macar). Tırnak tek ifade sayılır: \"meydan muharebesi\". Büyük/küçük harf ve Türkçe şapka farkı YOK.":["Բաժանեք բառերը բացատներով — մնում են այն հոդվածները, որոնցում կան ԲՈԼՈՐԸ (Mohaç macar)։ Չակերտները համարվում են մեկ արտահայտություն՝ \"meydan muharebesi\"։ Մեծատառ/փոքրատառի և թուրքերենի գլխարկանիշի տարբերություն ՉԿԱ։", "0e488ddd"],
